def apply_revocation_event(redis_client, dlq, event, max_retries=4):
    for attempt in range(max_retries):
        try:
            if event['type'] == 'REVOKE_JTI':
                ttl = max(1, int(event['exp'] - time.time()))
                redis_client.setex(f"rev:jti:{event['jti']}", ttl, '1')
            elif event['type'] == 'BUMP_EPOCH':
                # Monotonic Lua/atomic guard so out-of-order events never regress min_epoch
                redis_client.eval(
                    "local cur = tonumber(redis.call('GET', KEYS[1]) or '0'); "
                    "if tonumber(ARGV[1]) > cur then redis.call('SET', KEYS[1], ARGV[1], 'EX', ARGV[2]) end;",
                    1, f"rev:epoch:{event['user_id']}", str(event['epoch']), str(event['ttl'])
                )
            return True
        except RedisTransientError:
            if attempt == max_retries - 1:
                dlq.publish(event, reason='regional_redis_write_failed')
                return False
            time.sleep(min(2.0, (0.05 * (2 ** attempt)) + random.uniform(0, 0.05)))
